from google import genai



def select_platform_resource(model_name, config=None):
    config = config or {}
    with genai.Client(vertexai=True, project=config["project_id"], location=config["location"]) as client:
        model = client.models.get(model_name)
    return model

from google import genai



def stream_platform_generation(payload, config=None):
    config = config or {}
    with genai.Client(vertexai=True, project=config["project_id"], location=config["location"]) as client:
        response = client.models.generate_content(model="gemini-2.5-flash", contents=payload["text"], stream=True)
        for chunk in response:
            yield chunk

from google import genai



def collect_platform_metadata(payload, config=None):
    config = config or {}
    with genai.Client(vertexai=True, project=config["project_id"], location=config["location"]) as client:
        response = client.models.generate_content(model="gemini-2.5-flash", contents=payload["text"])
        metadata = {
            "text": response.text,
            "usage": response.usage,
            "resource_id": response.resource_id,
            "model_handle": response.model_handle
        }
    return metadata

from google import genai



def get_model_client(config=None):
    config = config or {}
    return genai.Client(vertexai=True, project=config["project_id"], location=config["location"])

def normalize_request(payload):
    return {
        "text": payload["text"]
    }


def normalize_response(response):
    return {
        "text": response.text,
        "usage": response.usage,
        "resource_id": response.resource_id,
        "model_handle": response.model_handle
    }
